const CACHE_TTL = 30 * 60; // 30 minuti

const LOCATIONS = [
  {
      id: "passo_costalunga",
          name: "Passo di Costalunga",
              sourceId: "90168c47-1b9d-442f-8e83-10cfce7d8ac4",
                },
                  {
                      id: "passo_nigra",
                          name: "Passo Nigra",
                              sourceId: "bb0a33cd-69cd-442f-b5f6-40b0453af396",
                                },
                                  {
                                      id: "passo_sella",
                                          name: "Passo Sella",
                                              sourceId: "3080a9af-d7bb-49cc-8747-d6bb51408267",
                                                },
                                                  {
                                                      id: "passo_pordoi",
                                                          name: "Passo Pordoi",
                                                              sourceId: "1f9da140-ca05-4cd6-adbb-1dda1f24d872",
                                                                },
                                                                  {
                                                                      id: "passo_san_pellegrino",
                                                                          name: "Passo San Pellegrino",
                                                                              sourceId: "5d71d863-9b91-49db-a24a-84430b367c30",
                                                                                },
                                                                                  {
                                                                                      id: "passo_rolle",
                                                                                          name: "Passo Rolle",
                                                                                              sourceId: "3a541c02-d2f4-4eb6-b300-88ae21a009be",
                                                                                                },
                                                                                                ];

                                                                                                function corsHeaders(extra = {}) {
                                                                                                  return {
                                                                                                      "Access-Control-Allow-Origin": "*",
                                                                                                          "Access-Control-Allow-Methods": "GET, OPTIONS",
                                                                                                              "Access-Control-Allow-Headers": "Content-Type",
                                                                                                                  "Content-Type": "application/json; charset=utf-8",
                                                                                                                      "Cache-Control": `public, max-age=${CACHE_TTL}`,
                                                                                                                          ...extra,
                                                                                                                            };
                                                                                                                            }

                                                                                                                            function upstreamUrl(sourceId) {
                                                                                                                              return `https://meteo.report/var/data/forecasts/${sourceId}.json`;
                                                                                                                              }

                                                                                                                              async function fetchOne(location) {
                                                                                                                                const url = upstreamUrl(location.sourceId);

                                                                                                                                  try {
                                                                                                                                      const response = await fetch(url, {
                                                                                                                                            headers: {
                                                                                                                                                    "Accept": "application/json",
                                                                                                                                                            "User-Agent": "Mozilla/5.0",
                                                                                                                                                                  },
                                                                                                                                                                        cf: {
                                                                                                                                                                                cacheTtl: CACHE_TTL,
                                                                                                                                                                                        cacheEverything: true,
                                                                                                                                                                                              },
                                                                                                                                                                                                  });

                                                                                                                                                                                                      if (!response.ok) {
                                                                                                                                                                                                            return {
                                                                                                                                                                                                                    id: location.id,
                                                                                                                                                                                                                            name: location.name,
                                                                                                                                                                                                                                    source_id: location.sourceId,
                                                                                                                                                                                                                                            ok: false,
                                                                                                                                                                                                                                                    status: response.status,
                                                                                                                                                                                                                                                            error: `HTTP ${response.status}`,
                                                                                                                                                                                                                                                                  };
                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                          const data = await response.json();

                                                                                                                                                                                                                                                                              return {
                                                                                                                                                                                                                                                                                    id: location.id,
                                                                                                                                                                                                                                                                                          name: location.name,
                                                                                                                                                                                                                                                                                                source_id: location.sourceId,
                                                                                                                                                                                                                                                                                                      ok: true,
                                                                                                                                                                                                                                                                                                            start: data.start ?? null,
                                                                                                                                                                                                                                                                                                                  end: data.end ?? null,
                                                                                                                                                                                                                                                                                                                        interval_minutes: 180,
                                                                                                                                                                                                                                                                                                                              forecast_180: data["180"] ?? null,
                                                                                                                                                                                                                                                                                                                                  };

                                                                                                                                                                                                                                                                                                                                    } catch (error) {
                                                                                                                                                                                                                                                                                                                                        return {
                                                                                                                                                                                                                                                                                                                                              id: location.id,
                                                                                                                                                                                                                                                                                                                                                    name: location.name,
                                                                                                                                                                                                                                                                                                                                                          source_id: location.sourceId,
                                                                                                                                                                                                                                                                                                                                                                ok: false,
                                                                                                                                                                                                                                                                                                                                                                      status: null,
                                                                                                                                                                                                                                                                                                                                                                            error: String(error?.message || error),
                                                                                                                                                                                                                                                                                                                                                                                };
                                                                                                                                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                  export default {
                                                                                                                                                                                                                                                                                                                                                                                    async fetch(request) {
                                                                                                                                                                                                                                                                                                                                                                                        const url = new URL(request.url);

                                                                                                                                                                                                                                                                                                                                                                                            // Gestione CORS
                                                                                                                                                                                                                                                                                                                                                                                                if (request.method === "OPTIONS") {
                                                                                                                                                                                                                                                                                                                                                                                                      return new Response(null, {
                                                                                                                                                                                                                                                                                                                                                                                                              status: 204,
                                                                                                                                                                                                                                                                                                                                                                                                                      headers: corsHeaders(),
                                                                                                                                                                                                                                                                                                                                                                                                                            });
                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                    // Accettiamo soltanto GET
                                                                                                                                                                                                                                                                                                                                                                                                                                        if (request.method !== "GET") {
                                                                                                                                                                                                                                                                                                                                                                                                                                              return new Response(
                                                                                                                                                                                                                                                                                                                                                                                                                                                      JSON.stringify({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                error: "Method not allowed",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          status: 405,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    headers: corsHeaders(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          // Endpoint consentiti
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    url.pathname !== "/" &&
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          url.pathname !== "/forecast"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return new Response(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            JSON.stringify({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      error: "Not found",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                endpoints: ["/", "/forecast"],
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          status: 404,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    headers: corsHeaders(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const cache = caches.default;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const cacheKey = new Request(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    `${url.origin}/forecast`,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  method: "GET",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // Prima controlliamo se abbiamo già
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // una risposta aggregata in cache.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const cached = await cache.match(cacheKey);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (cached) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  return cached;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const generatedAt = new Date().toISOString();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              // IMPORTANTE:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  // tutte le località vengono richieste
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      // contemporaneamente, non una dopo l'altra.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const locations = await Promise.all(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                LOCATIONS.map(fetchOne)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const successful =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              locations.filter(x => x.ok).length;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const failed =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        locations.length - successful;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const payload = {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  source: "meteo.report",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        generated_at: generatedAt,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              cache_ttl_seconds: CACHE_TTL,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    interval_minutes: 180,

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          total_locations: locations.length,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                successful_locations: successful,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      failed_locations: failed,

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            locations,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    /*
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          Se almeno una località ha risposto,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                restituiamo comunque HTTP 200.

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      In questo modo un problema, per esempio,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            con Passo Rolle non impedisce alla pagina
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  di utilizzare Sella, Pordoi ecc.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      */
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const status =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                successful > 0 ? 200 : 502;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const response = new Response(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          JSON.stringify(payload, null, 2),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        status,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                headers: corsHeaders({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          "X-Worker-Cache": "MISS",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // Mettiamo in cache soltanto una risposta
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // che contiene almeno una località valida.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (status === 200) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              await cache.put(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      cacheKey,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              response.clone()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return response;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              };